   404→        const toggleButton = document.getElementById('darkModeToggle');
   405→        const html = document.documentElement;
   406→
   407→        // Load saved theme
   408→        const savedTheme = localStorage.getItem('theme');
   409→        if (savedTheme === 'dark') {
   410→            html.setAttribute('data-theme', 'dark');
   411→            toggleButton.textContent = '☀️ Light Mode';
   412→        }
   413→
   414→        // Toggle theme
   415→        toggleButton.addEventListener('click', () => {
   416→            const currentTheme = html.getAttribute('data-theme');
   417→            if (currentTheme === 'dark') {
   418→                html.removeAttribute('data-theme');
   419→                localStorage.setItem('theme', 'light');
   420→                toggleButton.textContent = '🌙 Dark Mode';
   421→            } else {
   422→                html.setAttribute('data-theme', 'dark');
   423→                localStorage.setItem('theme', 'dark');
   424→                toggleButton.textContent = '☀️ Light Mode';
   425→            }
   426→        });
